files./etc/caddy/Caddyfile:
# LAN access via IP: redirect to the domain. This used to serve the whole
# console and API over plain HTTP, which put LAN sign-ins on the wire in
# cleartext (security review, 0.18.22).
http://192.0.2.10 {
    redir https://remote.example.com{uri} permanent
}

# External access via domain (HTTPS with auto TLS)
remote.example.com {
    # Uploaded branding. Served as inert files: a logo has no business running
    # script, and these are same-origin with the console.
    handle /uploads/* {
        root * /opt/reboot-remote
        header Content-Security-Policy "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox"
        header X-Content-Type-Options nosniff
        file_server
    }

    # RustDesk over 443. The client (allow-websocket=Y, api-server=https://…)
    # resolves a domain rendezvous/relay to wss://<host>/ws/id and
    # wss://<host>/ws/relay on 443 — see hbb_common check_ws(). Proxying those
    # to hbbs 21118 / hbbr 21119 lets endpoints on networks that only permit
    # 443 egress reach the server without opening 21115-21119.
    handle /ws/id {
        reverse_proxy localhost:21118
    }

    handle /ws/relay {
        reverse_proxy localhost:21119
    }

    handle /api/* {
        reverse_proxy localhost:3001 {
            transport http {
                response_header_timeout 300s
            }
            lb_retries 1
        }
    }

    handle /* {
        reverse_proxy localhost:3000 {
            header_up Host {http.request.header.host}
        }
    }

    header {
        Strict-Transport-Security "max-age=31536000; includeSubDomains; preload"
        X-Content-Type-Options nosniff
        X-Frame-Options DENY
        Referrer-Policy strict-origin-when-cross-origin
        -Server
    }

    encode gzip

    log {
        output file /var/log/caddy/reboot-remote.log
        format json
    }
}

# Approval signer, its own origin.
approve.example.com {
    handle {
        respond 404
    }
}
